<?php require __DIR__.'/bootstrap.php';$p=db();$d=body();switch(method()){case'GET':respond($p->query('SELECT * FROM search_terms ORDER BY active DESC,term')->fetchAll());case'POST':requireFields($d,['term']);$p->prepare('INSERT INTO search_terms(term,weight,active,notes) VALUES(?,?,?,?)')->execute([clean($d['term']),(int)($d['weight']??10),(int)($d['active']??1),clean($d['notes']??'')]);respond(['id'=>insertedId($p,'search_terms')],201);case'PUT':requireFields($d,['id','term']);$p->prepare('UPDATE search_terms SET term=?,weight=?,active=?,notes=? WHERE id=?')->execute([clean($d['term']),(int)$d['weight'],(int)$d['active'],clean($d['notes']??''),(int)$d['id']]);respond(['updated'=>true]);case'DELETE':requireFields($d,['id']);$p->prepare('DELETE FROM search_terms WHERE id=?')->execute([(int)$d['id']]);respond(['deleted'=>true]);default:fail('Método não permitido',405);}
